import {controlConnections,nodeRuntime,runtimeCandidates,controlHost} from './runtime-control.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(label,key,value)=>`<label>${label}<input data-key="${key}" value="${esc(value)}"></label>`;
function runtimeSelect(s,n,key,value){return `<label>Управляющий runtime<select data-key="${key}"><option value="">Не подключён</option>${runtimeCandidates(s,n).map(r=>`<option value="${esc(r.id)}" ${r.id===value?'selected':''}>${esc(r.name)} · ${esc(r.services.daemon.endpoint)}</option>`).join('')}</select></label>`}
export function controlUI(s,n){let h='';
 if(n.type==='k8s_node')h+=`<div class="section">УПРАВЛЕНИЕ POD</div>${runtimeSelect(s,n,'kubernetes.runtimeId',n.services.kubernetes.runtimeId)}<p>Пунктирные розовые стрелки соединяют отдельные службы kubelet и containerd с контейнерами. Pod и его NIC сохраняются независимо от этих связей.</p>`;
 if(n.type==='containerd')h+=`<div class="section">CONTAINERD · CRI SERVER</div>${field('CRI endpoint · локальный socket','daemon.endpoint',n.services.daemon.endpoint)}${field('Namespace runtime','daemon.namespace',n.services.daemon.namespace)}${field('Версия (описание)','daemon.version',n.services.daemon.version)}<p>Работает в ОС ${esc(controlHost(s,n)?.name)}. Запросы kubelet используют CRI / gRPC через socket; управление контейнерами абстрагирует shim / OCI runtime. Эти стрелки не переносят HTTP-пакет.</p>`;
 if(n.type==='kubelet'){const group=s.nodes.find(p=>p.id===n.parent&&p.type==='k8s_node'),runtime=group?nodeRuntime(s,group):runtimeCandidates(s,n).find(r=>r.id===n.services.agent.runtimeId);h+=`<div class="section">KUBELET · CRI CLIENT</div>${field('Версия (описание)','agent.version',n.services.agent.version)}${group?`<p>Runtime выбирается у группы ${esc(group.name)}.</p>`:runtimeSelect(s,n,'agent.runtimeId',n.services.agent.runtimeId)}<div class="hint">${runtime?'CRI → '+esc(runtime.name)+'<br>'+esc(runtime.services.daemon.endpoint):'Связь с runtime не настроена'}</div><p>Управляет жизненным циклом Pod; сетевые пакеты приложения не проходят через kubelet.</p>`}
 if(['kubelet','containerd','k8s_container'].includes(n.type)){const edges=controlConnections(s).filter(e=>e.source.id===n.id||e.target.id===n.id);h+=`<div class="section">СВЯЗИ УПРАВЛЕНИЯ · ${edges.length}</div>${edges.map(e=>`<div class="hint"><b>CTRL · ${esc(e.source.name)} → ${esc(e.target.name)}</b><p>${esc(e.label)}</p>${esc(e.detail)}</div>`).join('')||'<p>Связей управления нет. Выберите containerd у группы узла или kubelet.</p>'}`}
 return h;
}
